//! 🖍️ Borrowed background traversal retains only bounded geometry and numeric source cursors.
use super::*;
use semio_framework_io_ports::{VectorSceneCursor,VectorSceneGrant,VectorSceneEvent,VectorRgba,VectorSegment,VectorStyleRef};
use semio_s_artifact_stdio_contract::part21::Part21Instance;
use semio_s_artifact_stdio_step_snapshot::standards::v_ap214::subsets::base::io::draughting::DraughtingWriter;
#[path="📐️geometry/🦀️.rs"]mod geometry;
use geometry::{IDENTITY,matrix,multiply,apply};
#[derive(Clone,Copy,Debug)]struct Paint{fill:Option<[f64;3]>,stroke:Option<[f64;3]>,width:f64}
impl Default for Paint{fn default()->Self{Self{fill:Some([0.0,0.0,0.0]),stroke:None,width:1.0}}}
fn rgb(value:Option<VectorRgba>)->Option<[f64;3]>{value.map(|color|[f64::from(color.r),f64::from(color.g),f64::from(color.b)])}
fn grant()->VectorSceneGrant{VectorSceneGrant{maximum_source_items:65536,maximum_depth:256,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536}}
#[derive(Debug)]pub(super) struct StepBackground{source:VectorSceneCursor,styles:VectorSceneCursor,lookup:bool,candidate:bool,compare:usize,pending:u8,paint:Paint,visible:bool,transform:[f64;16],parents:Vec<[f64;16]>,points:[[f64;3];65],point_count:usize,current:[f64;2],start:[f64;2],node:usize,part:usize,text_offset:usize,text_x:f64,text_y:f64,image_done:bool}
impl StepBackground{
 pub(super) fn new()->Self{Self{source:VectorSceneCursor::new(),styles:VectorSceneCursor::new(),lookup:false,candidate:false,compare:0,pending:0,paint:Default::default(),visible:true,transform:IDENTITY,parents:Vec::new(),points:[[0.0;3];65],point_count:0,current:[0.0;2],start:[0.0;2],node:0,part:0,text_offset:0,text_x:0.0,text_y:0.0,image_done:false}}
 fn point(&self,x:f64,y:f64,height:f64)->[f64;3]{let point=apply(self.transform,x,y);[point[0]*super::geometry::MM,(height-point[1])*super::geometry::MM,0.0]}
 fn flush(&mut self,writer:&mut DraughtingWriter,fill:bool)->Result<Vec<Part21Instance>,String>{if self.point_count<2{self.point_count=0;return Ok(Vec::new())}let name=format!("background-{}-{}",self.node,self.part);self.part+=1;if self.paint.stroke.is_some(){let scale=(self.transform[0]*self.transform[5]-self.transform[1]*self.transform[4]).abs().sqrt();writer.set_curve_width(self.paint.width*scale*super::geometry::MM)?;}let output=writer.path(&name,&self.points[..self.point_count],self.paint.stroke,if fill{self.paint.fill}else{None})?;self.point_count=0;Ok(output)}
 fn push(&mut self,point:[f64;3],writer:&mut DraughtingWriter,out:&mut Vec<Part21Instance>)->Result<(),String>{if self.point_count==65{if self.paint.fill.is_some(){return Err("layout.step.background-fill-point-limit".into());}let last=self.points[64];out.extend(self.flush(writer,false)?);self.points[0]=last;self.point_count=1;}self.points[self.point_count]=point;self.point_count+=1;Ok(())}
 fn finish_path(&mut self,writer:&mut DraughtingWriter)->Result<Vec<Part21Instance>,String>{if self.point_count>1&&self.paint.fill.is_some()&&self.points[0]!=self.points[self.point_count-1]{if self.point_count>=65{return Err("layout.step.background-fill-point-limit".into());}self.points[self.point_count]=self.points[0];self.point_count+=1;}self.flush(writer,true)}
 pub(super) fn advance(&mut self,doc:&LayoutSnapshot,page:&Page,writer:&mut DraughtingWriter)->Result<(bool,Vec<Part21Instance>),String>{
  if self.lookup{let leaf=semio_s_artifact_layout_layout_model::background_drawing_leaf(doc,&mut self.source,grant()).map_err(|error|error.to_string())?;let wanted=match leaf.event{VectorSceneEvent::BeginPath{style}|VectorSceneEvent::Text{style,..}=>style.ok_or("layout.step.background-style-source")?,_=>return Err("layout.step.background-style-source".into())};let mut allowance=grant();allowance.maximum_source_items=allowance.maximum_source_items.saturating_sub(leaf.receipt.source_items);if self.candidate{let event=semio_s_artifact_layout_layout_model::background_drawing_style(doc,&mut self.styles,allowance).map_err(|error|error.to_string())?.event;let VectorSceneEvent::Style(VectorStyleRef{name,fill,stroke,stroke_width,..})=event else{return Err("layout.step.background-style-source".into())};if name.len()!=wanted.len(){self.candidate=false;self.compare=0;return Ok((false,Vec::new()))}let end=(self.compare+256).min(name.len());if name.as_bytes()[self.compare..end]!=wanted.as_bytes()[self.compare..end]{self.candidate=false;self.compare=0;}else{self.compare=end;if end==name.len(){self.paint=Paint{fill:rgb(fill),stroke:if stroke_width==Some(0.0){None}else{rgb(stroke)},width:stroke_width.filter(|width|*width!=0.0).unwrap_or(1.0)};self.lookup=false;self.candidate=false;self.styles=VectorSceneCursor::new();}}}else{let event=semio_s_artifact_layout_layout_model::background_drawing_step(doc,&mut self.styles,allowance).map_err(|error|error.to_string())?.event;match event{VectorSceneEvent::Canvas{..}=>{},VectorSceneEvent::Style(_)=>{self.candidate=true;self.compare=0;},_=>return Err("layout.step.background-missing-style".into())}}return Ok((false,Vec::new()))}
  if self.pending==2{let event=semio_s_artifact_layout_layout_model::background_drawing_leaf(doc,&mut self.source,grant()).map_err(|error|error.to_string())?.event;let VectorSceneEvent::Text{value,at,..}=event else{return Err("layout.step.background-text-source".into())};if self.text_offset>=value.len(){self.pending=0;return Ok((false,Vec::new()))}let mut end=(self.text_offset+512).min(value.len());while !value.is_char_boundary(end){end-=1;}if let Some(line)=value[self.text_offset..end].find('\n'){end=self.text_offset+line+1;}let literal=&value[self.text_offset..end];let point=self.point(at.x+self.text_x,at.y+self.text_y,page.height);let width=literal.chars().count().max(1)as f64*7.2*self.transform[0].hypot(self.transform[1]);let size=12.0*self.transform[4].hypot(self.transform[5]);if size<=1e-9||width<=1e-9{return Err("layout.step.background-text-transform".into());}let output=writer.text(&format!("background-text-{}@{}",self.node,self.text_offset),literal,point,-self.transform[1].atan2(self.transform[0]),width*super::geometry::MM,size*super::geometry::MM,size*super::geometry::MM,self.paint.fill.or(self.paint.stroke))?;self.text_offset=end;if literal.ends_with('\n'){self.text_x=0.0;self.text_y+=14.4;}else{self.text_x+=literal.chars().count()as f64*7.2;}return Ok((false,output))}
  if self.pending==3{let event=semio_s_artifact_layout_layout_model::background_drawing_leaf(doc,&mut self.source,grant()).map_err(|error|error.to_string())?.event;let VectorSceneEvent::Image{at,width,height,mime,bytes}=event else{return Err("layout.step.background-image-source".into())};if !self.image_done{let points=[[at.x,at.y],[at.x+width,at.y],[at.x+width,at.y+height],[at.x,at.y+height],[at.x,at.y]].map(|[x,y]|self.point(x,y,page.height));self.image_done=true;writer.set_curve_width(super::geometry::MM)?;return Ok((false,writer.path(&format!("background-image-{}",self.node),&points,Some([0.0,0.0,0.0]),None)?))}if mime.len()>255{return Err("layout.step.background-image-mime".into());}let label=format!("{} ({} bytes)",mime,bytes.len());if label.len()>512{return Err("layout.step.background-image-identity".into());}self.pending=0;return Ok((false,writer.text(&format!("background-image-{} source",self.node),&label,self.point(at.x,at.y+9.0,page.height),-self.transform[1].atan2(self.transform[0]),width.abs().max(1.0)*super::geometry::MM,9.0*super::geometry::MM,9.0*super::geometry::MM,None)?))}
  let event=semio_s_artifact_layout_layout_model::background_drawing_step(doc,&mut self.source,grant()).map_err(|error|error.to_string())?.event;let mut out=Vec::new();match event{
   VectorSceneEvent::Canvas{canvas,..}=>{if let Some(color)=canvas.background{let points=[[0.0,0.0],[canvas.width,0.0],[canvas.width,canvas.height],[0.0,canvas.height],[0.0,0.0]].map(|[x,y]|self.point(x,y,page.height));out.extend(writer.path("background-canvas",&points,None,rgb(Some(color)))?);}},
   VectorSceneEvent::Style(_)=>{},VectorSceneEvent::BeginLayer{visible,..}=>{self.visible=visible;self.transform=IDENTITY;},VectorSceneEvent::EndLayer=>{},
   VectorSceneEvent::BeginGroup{transform}if self.visible=>{if self.parents.len()>=256{return Err("layout.step.background-transform-depth".into());}self.parents.push(self.transform);self.transform=multiply(self.transform,matrix(transform));},VectorSceneEvent::EndGroup if self.visible=>{self.transform=self.parents.pop().ok_or("layout.step.background-transform-stack")?;},
   VectorSceneEvent::BeginPath{style}if self.visible=>{self.node+=1;self.part=0;self.point_count=0;self.pending=1;self.paint=Default::default();self.lookup=style.is_some();},
   VectorSceneEvent::Segment(segment)if self.visible=>{match segment{
    VectorSegment::MoveTo{to}=>{if self.point_count>0{if self.paint.fill.is_some(){return Err("layout.step.background-compound-fill".into());}out.extend(self.flush(writer,false)?);}self.current=[to.x,to.y];self.start=self.current;let point=self.point(to.x,to.y,page.height);self.push(point,writer,&mut out)?;},
    VectorSegment::LineTo{to}=>{let point=self.point(to.x,to.y,page.height);self.push(point,writer,&mut out)?;self.current=[to.x,to.y];},
    VectorSegment::CubicTo{c1,c2,to}=>{for[x,y]in geometry::cubic_points(self.current,[c1.x,c1.y],[c2.x,c2.y],[to.x,to.y]){let point=self.point(x,y,page.height);self.push(point,writer,&mut out)?;}self.current=[to.x,to.y];},
    VectorSegment::QuadTo{c,to}=>{for[x,y]in geometry::quad_points(self.current,[c.x,c.y],[to.x,to.y]){let point=self.point(x,y,page.height);self.push(point,writer,&mut out)?;}self.current=[to.x,to.y];},
    VectorSegment::ArcTo{rx,ry,x_rotation,large_arc,sweep,to}=>{for[x,y]in geometry::arc_points(self.current,[to.x,to.y],[rx,ry],x_rotation,large_arc,sweep)?{let point=self.point(x,y,page.height);self.push(point,writer,&mut out)?;}self.current=[to.x,to.y];},VectorSegment::Close=>{let point=self.point(self.start[0],self.start[1],page.height);if self.point_count==0||self.points[self.point_count-1]!=point{self.push(point,writer,&mut out)?;}self.current=self.start;},
   }},VectorSceneEvent::EndPath if self.visible=>{out.extend(self.finish_path(writer)?);self.pending=0;},
   VectorSceneEvent::Text{style,..}if self.visible=>{self.node+=1;self.pending=2;self.text_offset=0;self.text_x=0.0;self.text_y=0.0;self.paint=Default::default();self.lookup=style.is_some();},VectorSceneEvent::Image{..}if self.visible=>{self.node+=1;self.pending=3;self.image_done=false;},VectorSceneEvent::Done=>return Ok((true,out)),_=>{}
  }Ok((false,out))
 }
 pub(super) fn next_release_bytes(&self)->usize{if self.source.next_release_bytes()>0{self.source.next_release_bytes()}else if self.styles.next_release_bytes()>0{self.styles.next_release_bytes()}else{self.parents.capacity()*std::mem::size_of::<[f64;16]>()}}
 pub(super) fn close_one(&mut self,bytes:usize)->bool{let demand=self.next_release_bytes();if demand>bytes{return false;}if self.source.next_release_bytes()>0{return self.source.close_one(bytes)}if self.styles.next_release_bytes()>0{return self.styles.close_one(bytes)}if self.parents.capacity()>0{self.parents=Vec::new();return true}false}
 pub(super) fn terminal_is_empty(&self)->bool{self.source.terminal_is_empty()&&self.styles.terminal_is_empty()&&self.parents.capacity()==0}
}
